-- c001-v002: اور اپفیہ–کو وہ بہن اور ارخپس–کو وہ ہم–سپاہی ہمارے اور وہ میں گھر تیرے کلیسیا–کو
-- c001-v003: فضل تمہیں اور سلامتی سے خدا باپ–سے ہمارے اور خداوند یسوع مسیح
-- c001-v004: میں–شکر–کرتا–ہوں کے خدا–کا میرے ہمیشہ ذکر تیرا کرتے–ہوئے پر اُن دعاؤں میری
-- c001-v005: سُنتے–ہوئے تیری وہ محبت اور وہ ایمان جو تو–رکھتا–ہے طرف کے خداوند یسوع اور لیے سارے اُن مقدسوں–کے
-- c001-v006: تاکہ وہ شراکت کے ایمان–کے تیرے مؤثر ہو میں پہچان ہر نیکی–کی جو میں ہم–میں لیے مسیح
-- c001-v007: خوشی کیونکہ بہت میں–نے–پائی اور تسلی پر وہ محبت تیری کہ وہ دل کے مقدسوں–کے آرام–پائے–ہیں ذریعے تیرے بھائی
-- c001-v008: اِس–لیے بہت میں مسیح دلیری رکھتے–ہوئے حکم–دینا تجھے وہ مناسب
-- c001-v009: ذریعے وہ محبت–کے بلکہ میں–التجا–کرتا–ہوں ایسا ہوتے–ہوئے جیسا پولس بوڑھا اب لیکن بھی قیدی مسیح یسوع–کا
-- c001-v010: میں–التجا–کرتا–ہوں تجھ–سے سے کے میرے بچے–کے جس میں–نے–جنا میں اُن قید–میں انیسمس–کو
-- c001-v011: جو کبھی تیرے–لیے بےکار اب لیکن بھی تجھے بھی مجھے کارآمد
-- c001-v012: جس میں–نے–واپس–بھیجا تجھے اُسے یہ ہے وہ میرا دل
-- c001-v013: جس میں چاہتا–تھا پاس اپنے رکھنا تاکہ واسطے تیرے میری خدمت–کرے میں اُن قید کے خوشخبری–کی
-- c001-v014: بغیر لیکن کی تیری رائے کچھ–نہیں میں–نے–چاہا کرنا تاکہ نہ جیسے مطابق مجبوری وہ نیکی تیری ہو بلکہ مطابق اپنی–خوشی–سے
-- c001-v015: شاید کیونکہ اِس–لیے یہ جدا–ہوا لیے گھڑی–کے تاکہ ابدی اُسے تُو–رکھے
-- c001-v016: اب–نہیں جیسے غلام بلکہ سے–بڑھ–کر غلام بھائی پیارا خاص–طور–پر مجھے کتنا لیکن زیادہ تجھے بھی میں جسم–میں بھی میں خداوند–میں
-- c001-v017: پس اگر مجھے تُو–سمجھتا–ہے شریک قبول–کر اُسے جیسے مجھے
-- c001-v018: اگر لیکن کچھ اُس–نے–نقصان–کیا–ہو تجھے یا قرض–ہو یہ میرے حساب–میں–لکھ
-- c001-v019: میں پولس لکھا سے اپنے ہاتھ–سے میں ادا–کروں–گا تاکہ–نہ میں کہوں تجھے کہ بھی اپنے–آپ–کو میرے تُو–دینا–ہے
-- c001-v020: ہاں بھائی میں تیرا فائدہ–اُٹھاؤں میں خداوند–میں آرام–دے میرا وہ دل میں مسیح–میں
-- c001-v021: بھروسہ–کرتے–ہوئے پر فرمانبرداری تیری میں–نے–لکھا تجھے جانتے–ہوئے کہ بھی سے–زیادہ جو میں–کہتا–ہوں کرے–گا
-- c001-v022: اور–ساتھ–ہی لیکن بھی تیار–کر میرے–لیے مہمان–خانہ امید–کرتا–ہوں کیونکہ کہ ذریعے کے دعاؤں تمہاری بخشا–جاؤں–گا تمہیں
-- c001-v023: سلام–بھیجتا–ہے تجھے اپفراس وہ ہم–قیدی میرا میں مسیح یسوع
-- c001-v024: مرقس ارسترخس دیماس لوقا وہ ہم–کار میرے
